.empty-box{
  height 170px;
  background-color: #F3F9FF;
  .shan {
	  width: 65px !important;
	  height: 50px !important;
  }
  &.style3{
	  width: 16px;
	  height: 134px;
	  border-radius: 0;
	  img {
		  width: 16px;
		  height: 100%;
	  }
  }
  &.on{
	  flex: 1
	  height 170px;
  }
}
.mobile-page {
  position: relative;
  width: auto;
  /*height: 140px;*/

  .banner {
    /*position: absolute;*/
    /*left: 0;*/
    /*top: 0;*/
    width: 100%;
    margin-top 0;
		&.on{
			margin-top -96px;
		}

    img {
      width: 100%;
      height: 100%;
      border-radius: 6px;
    }
  }

  .bg {
    width: 100%;
    height: 96px;
  }
}

.dot {
  position: absolute;
  left: 0;
  bottom: 0;
  width: 100%;
  display: flex;
  align-items: center;

  &.on{
	  .dot-item{
		  width: 5px;
		  height: 5px;
		  &.ons{
			 width: 9px;
			 height: 5px;
			 border-radius: 4px; 
		  }
	  }
  }

  &.on2{
	  .dot-item{
		  width: 10px;
		  height: 3px;
		  border-radius: 4px;
	  }
  }

  .dot-item {
    width: 6px;
    height: 6px;
    background: #DDDDDD;
    border-radius: 50%;
    margin: 0 3px;
  }

  .line-dot{
	  width: 30px;
	  height: 3px;
	  border-radius: 4px;
	  background-color: #DDDDDD;
	  .item{
		  width: 10px;
		  height: 100%;
		  border-radius: 4px;
		  background-color: #E93323;
	  }
  }

  &.number{
	  width: 40px;
	  height: 18px;
	  border-radius: 100px;
	  background: rgba(0,0,0,0.3);
	  color: #fff;
	  font-size: 8px;
	  .num{
		  width: 22px;
		  height: 100%;
		  border-radius: 20px 0 20px 20px;
		  background: rgba(0,0,0,0.1);
		  font-size: 10px;
		  text-align: center
		  line-height: 18px;
	  }
	  .numCon{
		  width: 18px;
		  text-align: center;
		  line-height: 18px;
	  }
  }
}
